import { Metadata } from 'next';
// export const metadata = {
//   title: 'Next.js',
//   description: 'Generated by Next.js',
// } // * simple form, BUT now trying the title object for more functionality
export const metadata :  Metadata = {
  title:{
    default:'SRJ',   // acts as fallback if no title specified for a route
    template:'%s | SRJ NEXT.JS', // for consistent title across project, used to add prefix or suffix to the existing route title, just shift the "%s" thing for prefixing or suffixing 
    // absolute:'', only mentioned here, but to be used with the particular page.tsx files within the routes, this is to break free or get rid of the template value for SOME routes if we want to!!, think of it like counter-template, or just to remove it, (like /about), it can ALSO be used to override the parent layout.tsx title value 
  },
  description:"Generated by Next.js"
}
// * Notes 
// default wala title value will be taken only if there is no title specified in the page.tsx of that route (like /dashboard for this project), so the title would become 'SRJ' for the /dashboard route and you won't see the template title value being suffixed or prefixed

// But, the template value will be added - suffixed or prefixed when you havge already defined the title value for the route in their page.tsx  (like /blog route for this project)

export default function RootLayout({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <html lang="en">
      <body>
        <header style={{backgroundColor:'lightblue', padding:'1rem'}}>
          <p>This is the header</p>
        </header>

        {children}

        <footer style={{backgroundColor:'tomato', padding:'1rem'}}>
          <p>This is the footer</p>
        </footer>
        </body>
    </html>
  )
}
// * Notes 

// Every layout component needs a children where the page content will go, so in this case the page.tsx at this level of hierarchy becomes the children when layout.tsx renders

// without layout.tsx the page.tsx cannot render, and thus even if we try to delete this layout.tsx and then refresh the page then it will automatically re-appear, so this layout.tsx is NOT optional

// So keep the children prop and the write html,css around it, if you do this then you will be able to see the same layout on every route but the children prop will render different unique content based on the route